~~~js
import assert from 'node:assert/strict';
import { normalizeLog as n } from './normalize-log.mjs';

assert.equal(
  n('2026-01-01T12:00:00Z [pid=12] ECONNREFUSED 127.0.0.1:51234'),
  n('2026-09-02T13:01:42Z [pid=99] ECONNREFUSED 127.0.0.1:62345'));
assert.equal(n(n('port=43210')), n('port=43210'));
assert.notEqual(n("TypeError: property 'name'"),
                n("TypeError: property 'email'"));
assert.notEqual(n('HTTP 404'), n('HTTP 500'));
assert.equal(n('at run (file.ts:12345:8)'), 'at run (file.ts:12345:8)');
