Capture the outbound GA4 request with Playwright's request event, and validate it against a versioned fixture. The listener must be armed before clicking.

Google defines add_to_cart using event-level currency/value and an items array; value represents the added items' price × quantity, excluding shipping and tax. An event-level custom item_id alone would not validate that ecommerce structure. genui{"citation":{"ref":"turn11view7"}}

The example assumes one seeded product priced at USD 49.99, quantity one, an empty cart, and analytics consent already accepted through your test setup. Replace the route, measurement ID, and expected values with your tracking contract.

~~~ts
// tests/tracking-plan.ts
type CartPayload = {
  currency: string;
  value: number;
  items: { item_id: string; price: number; quantity: number }[];
};

export const addToCartPlan = {
  path: '/products/qa-sku-42',
  buttonName: 'Add to cart',
  measurementId: 'G-REPLACE_WITH_TEST_PROPERTY',
  expected: {
    currency: 'USD',
    value: 49.99,
    items: [{ item_id: 'QA-SKU-42', price: 49.99, quantity: 1 }],
  } satisfies CartPayload,
};
~~~

~~~ts
// tests/add-to-cart.analytics.spec.ts
import { test, expect, type Request } from '@playwright/test';
import { addToCartPlan as plan } from './tracking-plan';

function ga4Events(request: Request): URLSearchParams[] {
  const url = new URL(request.url());
  const allowedHost =
    /(^|\.)google-analytics\.com$/.test(url.hostname) ||
    url.hostname === 'analytics.google.com';
  if (!allowedHost || url.pathname !== '/g/collect') return [];

  const base = url.searchParams;
  const lines = (request.postData() ?? '')
    .split(/\r?\n/).filter(line => line.trim())
    .map(line => new URLSearchParams(line));
  const merge = (line: URLSearchParams) => {
    const event = new URLSearchParams(base);
    line.forEach((value, key) => event.set(key, value));
    return event;
  };

  if (!lines.length) return base.has('en') ? [base] : [];
  // Batch records each carry en; query parameters can be shared.
  if (lines.every(line => line.has('en'))) {
    return [
      ...(base.has('en') ? [base] : []),
      ...lines.map(merge),
    ];
  }
  // Single event split between query string and form POST body.
  if (lines.length === 1) {
    const event = merge(lines[0]);
    return event.has('en') ? [event] : [];
  }
  throw new Error('Unrecognized GA4 payload; inspect its transport format');
}

function numberParam(raw: string | null | undefined, field: string) {
  if (raw == null || raw.trim() === '' || !Number.isFinite(Number(raw))) {
    throw new Error('Missing or invalid numeric parameter: ' + field);
  }
  return Number(raw);
}

function ecommercePayload(params: URLSearchParams) {
  const items = [...params.entries()]
    .filter(([key]) => /^pr\d+$/.test(key))
    .sort(([a], [b]) => Number(a.slice(2)) - Number(b.slice(2)))
    .map(([, encoded]) => {
      // Common gtag web item encoding: id...~pr...~qt...
      const fields = Object.fromEntries(encoded.split('~')
        .map(part => [part.slice(0, 2), part.slice(2)]));
      return {
        item_id: fields.id,
        price: numberParam(fields.pr, 'item.price'),
        quantity: fields.qt === undefined ? 1 :
          numberParam(fields.qt, 'item.quantity'),
      };
    });
  return {
    currency: params.get('cu') ?? params.get('ep.currency'),
    value: numberParam(params.get('epn.value'), 'value'),
    items,
  };
}

test('add_to_cart emits correct ecommerce parameters', async ({ page }) => {
  await page.goto(plan.path); // baseURL comes from existing test config
  // Complete your existing consent fixture before this point.
  const [request] = await Promise.all([
    page.waitForRequest(r => ga4Events(r)
      .some(event => event.get('en') === 'add_to_cart')),
    page.getByRole('button', {
      name: plan.buttonName, exact: true,
    }).click(),
  ]);

  const matches = ga4Events(request)
    .filter(event => event.get('en') === 'add_to_cart');
  expect(matches, 'Expected one add_to_cart in this payload').toHaveLength(1);

  const event = matches[0];
  expect(event.get('v')).toBe('2');
  expect(event.get('tid')).toBe(plan.measurementId);
  expect(ecommercePayload(event)).toEqual(plan.expected);
});
~~~

The request continues normally; no routing mock, abort, dataLayer read, or DOM-derived analytics assertion is used. Playwright documents waiting for network events around the triggering action. genui{"citation":{"ref":"turn11view2"}}

