// api-tests/users.spec.ts
import { test, expect } from '@playwright/test';
import { UsersListSchema } from './contracts/users';

test('GET /api/users satisfies the list contract', async ({ request }) => {
  const response = await request.get('/api/users', {
    maxRedirects: 0, // A login redirect must not become a misleading 200.
    timeout: 10_000,
