    .toMatch(/^application\/(?:[a-z0-9.-]+\+)?json(?:\s*;|$)/i);

  const body: unknown = await response.json();
  const parsed = UsersListSchema.safeParse(body);

  expect(parsed.success, parsed.success
    ? 'Valid users response'
    : 'Schema violations:\n' + JSON.stringify(parsed.error.issues, null, 2)
