Register the product request before visiting the page, wait for its alias, then use a retrying DOM assertion for the count. This browser E2E example supplies three deterministic products.

Assumptions to adapt: the page is `/products`, it requests `GET /api/products` in the browser, its response is `{ products: [...] }`, and cards use `data-testid="product-card"`.

```ts
// cypress/e2e/products.cy.ts
describe('Product listing', () => {
  it('renders every loaded product', () => {
    const products = [
      { id: 'sku-1', name: 'Notebook', price: 8.5 },
      { id: 'sku-2', name: 'Pen', price: 2.25 },
      { id: 'sku-3', name: 'Desk lamp', price: 24 },
    ];

    cy.intercept(
      { method: 'GET', pathname: '/api/products' },
      {
        statusCode: 200,
        headers: { 'cache-control': 'no-store' },
        body: { products },
      },
    ).as('getProducts');

    cy.visit('/products');

    cy.wait('@getProducts')
      .its('response.statusCode')
      .should('eq', 200);

    cy.get('[data-testid="product-list"]')
      .find('[data-testid="product-card"]')
      .should('have.length', products.length);

    for (const product of products) {
      cy.contains(
        '[data-testid="product-card"]',
        product.name,
      ).should('be.visible');
    }
  });
});
```

