Use one test that creates an isolated empty database, applies the committed Prisma migrations, and then inspects the resulting schema. Keeping those operations in one test avoids order dependencies.

This template assumes **PostgreSQL, Vitest, and a Prisma datasource that reads `DATABASE_URL`**. Configure any direct migration URL to use the same test value. Supply a PostgreSQL image matching your production major and a complete list of expected physical table names, including any Prisma `@@map` mappings.

```bash
npm install --save-dev @testcontainers/postgresql pg @types/pg
```

Use the project's existing `prisma` and `vitest` dependencies.

```ts
// tests/migrations.test.ts
import { test, expect } from 'vitest';
import { PostgreSqlContainer } from '@testcontainers/postgresql';
import { Pool } from 'pg';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { createRequire } from 'node:module';

const execFileAsync = promisify(execFile);
const prismaCli = createRequire(import.meta.url).resolve('prisma');

async function applicationTables(pool: Pool) {
  const result = await pool.query<{ table_name: string }>(`
    SELECT table_name
    FROM information_schema.tables
    WHERE table_schema = 'public'
      AND table_type = 'BASE TABLE'
      AND table_name <> '_prisma_migrations'
  `);
  return result.rows.map(row => row.table_name).sort();
}

test('migrations apply to an empty database and create expected tables', async () => {
  const image = process.env.PG_TEST_IMAGE;
  const expected: unknown = JSON.parse(
    process.env.EXPECTED_TABLES_JSON ?? '[]',
  );

  if (!image) throw new Error('Set PG_TEST_IMAGE to the intended PostgreSQL image');
  if (
    !Array.isArray(expected) ||
    expected.length === 0 ||
    !expected.every(name => typeof name === 'string' && name.length > 0)
  ) {
    throw new Error('Set EXPECTED_TABLES_JSON to the complete expected table list');
  }

  const database = await new PostgreSqlContainer(image)
    .withDatabase('migration_check')
    .start();

  let pool: Pool | undefined;
  try {
    const url = database.getConnectionUri();
    pool = new Pool({ connectionString: url });

    expect(await applicationTables(pool)).toEqual([]);

    // Run the locally installed Prisma CLI against this container only.
    await execFileAsync(
      process.execPath,
      [prismaCli, 'migrate', 'deploy'],
      {
        cwd: process.cwd(),
        env: {
          ...process.env,
          DATABASE_URL: url,
          DIRECT_URL: url,
        },
        timeout: 60_000,
      },
    );

    expect(await applicationTables(pool)).toEqual([...expected].sort());
  } finally {
    try {
      await pool?.end();
    } finally {
      await database.stop();
    }
  }
}, 180_000);
```

Run with Docker available, replacing the placeholders:

```bash
PG_TEST_IMAGE='postgres:<production-compatible-tag>' \
EXPECTED_TABLES_JSON='["<physical_table_1>","<physical_table_2>"]' \
npx vitest run tests/migrations.test.ts
```

