Assuming a Node.js test suite and an OTLP HTTP collector, start one SDK in each test worker, create spans around the actual tests, and await shutdown in that same worker. A coordinator's global teardown cannot flush another process's SDK.

Install the compatible OTel packages and commit the resulting lockfile:

```bash
npm install --save-dev --save-exact @opentelemetry/api @opentelemetry/sdk-node @opentelemetry/exporter-trace-otlp-http @opentelemetry/resources
```

For Node's built-in test runner:

```js
// test-setup/tracing.mjs
import { after } from 'node:test';
import { randomUUID } from 'node:crypto';
import { trace, SpanStatusCode } from '@opentelemetry/api';
import { NodeSDK } from '@opentelemetry/sdk-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import { resourceFromAttributes } from '@opentelemetry/resources';

export const runId = process.env.TEST_RUN_ID ?? randomUUID();
const sdk = new NodeSDK({
  resource: resourceFromAttributes({
    'service.name': 'integration-tests',
    'test.suite': process.env.TEST_SUITE_NAME ?? 'integration',
    'test.run_id': runId,
  }),
  traceExporter: new OTLPTraceExporter({
    url: process.env.OTEL_EXPORTER_OTLP_TRACES_ENDPOINT
      ?? 'http://localhost:4318/v1/traces',
  }),
});

sdk.start();
after(async () => { await sdk.shutdown(); });

export async function traced(name, work) {
  return trace.getTracer('qa-tests').startActiveSpan(name, async span => {
    try {
      const result = await work();
      span.setStatus({ code: SpanStatusCode.OK });
      return result;
    } catch (error) {
      const exception = error instanceof Error ? error : new Error(String(error));
      span.recordException(exception);
      span.setStatus({ code: SpanStatusCode.ERROR });
      throw error;
    } finally {
      span.end();
    }
  });
}
```

```js
// tests/telemetry.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { traced, runId } from '../test-setup/tracing.mjs';

test('telemetry smoke', async () => {
  await traced('telemetry smoke', async () => assert.equal(2 + 2, 4));
  console.log(`test.run_id=${runId}`);
});
```

