Test the authorization boundary directly with two independent identities. This example assumes bearer authentication and a read-only `GET /api/orders/:id` endpoint. Seed two ordinary, unrelated customers and one private order each; substitute your actual route and response fields.

Playwright supports isolated request contexts, and disabling redirects prevents an unexpected login redirect from disguising the result. genui{"citation":{"refs":["turn28view0","turn28view1"]}}

```typescript
// tests/security/order-idor.spec.ts
import {
  test, expect, request as api,
  type APIRequestContext,
} from '@playwright/test';

function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error('Missing test configuration: ' + name);
  return value;
}

test('user A cannot read user B’s private order', async () => {
  test.setTimeout(20_000);

  const baseURL = required('TEST_BASE_URL');
  const tokenA = required('TEST_USER_A_TOKEN');
  const tokenB = required('TEST_USER_B_TOKEN');
  const orderA = required('TEST_USER_A_ORDER_ID');
  const orderB = required('TEST_USER_B_ORDER_ID');
  const privateNoteB = required('TEST_USER_B_PRIVATE_NOTE');

  expect(orderA).not.toBe(orderB);
  expect(tokenA === tokenB, 'Fixtures must use distinct users').toBe(false);

  const contexts: APIRequestContext[] = [];
  const path = (id: string) => '/api/orders/' + encodeURIComponent(id);
  const options = { maxRedirects: 0, failOnStatusCode: false };

  try {
    for (const token of [tokenA, tokenB]) {
      contexts.push(await api.newContext({
        baseURL,
        timeout: 5_000,
        extraHTTPHeaders: { Authorization: 'Bearer ' + token },
      }));
    }
    const [userA, userB] = contexts;

    // Positive controls: both identities work and both orders exist.
    const ownA = await userA.get(path(orderA), options);
    expect(ownA.status()).toBe(200);
    expect(await ownA.json()).toMatchObject({ id: orderA });

    const ownB = await userB.get(path(orderB), options);
    expect(ownB.status()).toBe(200);
    expect(await ownB.json()).toMatchObject({
      id: orderB,
      privateNote: privateNoteB, // Seeded synthetic content only.
    });

    // Attack: retain A's credentials and substitute B's object ID.
    const denied = await userA.get(path(orderB), options);
    expect([403, 404]).toContain(denied.status());
    expect(await denied.text()).not.toContain(privateNoteB);
  } finally {
    await Promise.all(contexts.map(context => context.dispose()));
  }
});
```

Choose **403**, or **404 if your API deliberately conceals resource existence**; tighten the assertion to your documented contract. A 401 is not a passing authorization result here: it would suggest invalid authentication. The positive controls prevent a missing route, nonexistent fixture, or universally denied endpoint from giving false confidence.

