Here is a self-contained **MSW 2.x + Vitest** example for an illustrative JSON payment API. Adapt its endpoint and schema to your provider contract. The included client demonstrates the retry policy; replace it with your actual payment client to test your application.

MSW 2 uses Fetch-style request/response handlers. Error scenarios below are checked before returning success, and per-test overrides use `server.use()`. genui{"citation":{"refs":["turn38view0","turn33search2"]}}

```typescript
// payment-api.test.ts — Node environment
import {
  beforeAll, afterAll, afterEach, test, expect,
} from 'vitest';
import { http, HttpResponse, delay } from 'msw';
import { setupServer } from 'msw/node';

const URL = 'https://payments.example.invalid/v1/payments';
const payload = { amount: 5000, currency: 'usd' };
const payment = {
  id: 'pay_test_1', status: 'succeeded', ...payload,
};
const success = () => HttpResponse.json(payment, { status: 201 });

// Move this reusable handler into test/mocks/payment-handlers.ts.
const handlers = [
  http.post(URL, async ({ request }) => {
    const scenario = request.headers.get('x-test-scenario');
    if (scenario === 'rate-limit') {
      return HttpResponse.json(
        { error: { code: 'rate_limited' } },
        { status: 429, headers: { 'Retry-After': '1' } },
      );
    }
    if (scenario === 'timeout') await delay(500);
    return success();
  }),
];

const server = setupServer(...handlers);
beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

// Illustrative client: at most three attempts, retry 503 only.
// Every attempt uses the SAME key for the same logical payment.
async function createPayment(
  scenario = 'success',
  timeoutMs = 1000,
) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const signal = AbortSignal.timeout(timeoutMs);
    let response: Response;
    try {
      response = await fetch(URL, {
        method: 'POST',
        signal,
        headers: {
          'Content-Type': 'application/json',
          'Idempotency-Key': 'test-payment-operation-1',
          'x-test-scenario': scenario,
        },
        body: JSON.stringify(payload),
      });
    } catch (error) {
      if (signal.aborted) throw new Error('Payment service timeout');
      throw error;
    }

    if (response.status === 503 && attempt < 2) {
      await new Promise(resolve =>
        setTimeout(resolve, 10 * 2 ** attempt));
      continue;
    }
    if (!response.ok) {
      throw Object.assign(new Error('Payment request failed'), {
        status: response.status,
        retryAfter: response.headers.get('Retry-After'),
      });
    }
    return response.json();
  }
  throw new Error('Retry attempts exhausted');
}

test('returns the successful payment', async () => {
  await expect(createPayment()).resolves.toEqual(payment);
});

test('surfaces 429 and Retry-After', async () => {
  await expect(createPayment('rate-limit')).rejects.toMatchObject({
    status: 429, retryAfter: '1',
  });
});

test('aborts a response slower than the client deadline', async () => {
  await expect(createPayment('timeout', 50))
    .rejects.toThrow('Payment service timeout');
});

test('retries two 503 responses and succeeds on attempt three', async () => {
  const calls: Array<{ key: string | null; body: unknown }> = [];
  server.use(http.post(URL, async ({ request }) => {
    calls.push({
      key: request.headers.get('Idempotency-Key'),
      body: await request.json(),
    });
    if (calls.length < 3) {
      return HttpResponse.json(
        { error: { code: 'temporarily_unavailable' } },
        { status: 503 },
      );
    }
    return success();
  }));

  await expect(createPayment()).resolves.toEqual(payment);
  expect(calls).toEqual(Array.from({ length: 3 }, () => ({
    key: 'test-payment-operation-1',
    body: payload,
  })));
});
```

